// Pseudo-code
struct Slot {
    atomic_uint64_t seq;
    void* data;
};

bool enqueue(void* item) {
    uint64_t pos = tail.load();
    Slot* slot = &buffer[pos & mask];
    uint64_t seq = slot->seq.load();
    if ((seq & mask) != (pos & mask)) return false;
    if (!tail.compare_exchange(pos, pos + 1)) return false;
    slot->data = item;
    slot->seq.store(pos + 1);
    return true;
}

void* dequeue() {
    uint64_t pos = head.load();
    Slot* slot = &buffer[pos & mask];
    uint64_t seq = slot->seq.load();
    if ((seq & mask) != (pos & mask)) return nullptr;
    if (!head.compare_exchange(pos, pos + 1)) return nullptr;
    void* item = slot->data;
    slot->seq.store(pos + capacity + 1);
    return item;
}
```

